"use client";

import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { api, ApiError, setCsrfToken } from "./api-client";
import type { AttentionRules, AuditItem, Bootstrap, CalendarEvent, CompanySettings, DashboardMetrics, Employee, Lead, Option, Priority, ReportData, Role, Stage, Task, User, View } from "./crm-types";
import { isEditableShortcutTarget, normalizedKeyboardKey } from "./keyboard";
import { EmployeesPanel, RequirementsPanel, TemplatesEditor, Communications, AssignmentAlerts } from "./operations";
import type { MessageTemplate } from "./crm-types";
import TrainingView from "./training-view";

const stages:Stage[]=["New","Contacted","Qualified","Viewing / Meeting","Follow-up","Won","Lost"];
const priorities:Priority[]=["Low","Normal","High","Urgent"];
const emptyMetrics:DashboardMetrics={active:0,new:0,unassigned:0,overdue:0,no_follow_up:0,neglected:0,won:0,lost:0,tasksOverdue:0,tasksToday:0,followUpsToday:0,viewingsToday:0,conversionRate:0,stages:{}};
const emptyReports:ReportData={sources:[],employees:[],lostReasons:[]};
const defaultCompany:CompanySettings={companyName:"Example Company",timezone:"Asia/Dubai",currency:"AED",internalUrl:"http://crm.company.local"};
const defaultRules:AttentionRules={newLeadHours:24,inactiveLeadHours:72,flagMissingFollowUp:true,flagUnassigned:true};
const safeText=(value:unknown)=>typeof value==="string"?value:"";
const safeLower=(value:unknown)=>safeText(value).toLowerCase();
const normalizePhone=(value:unknown)=>{let digits=safeText(value).replace(/\D/g,"");if(digits.startsWith("00"))digits=digits.slice(2);if(digits.startsWith("0")&&digits.length===10)digits=`971${digits.slice(1)}`;return digits;};
const initials=(value:unknown)=>{const name=safeText(value).trim();if(!name||name==="Unassigned")return "+";return name.split(/\s+/).filter(Boolean).map(part=>part[0]??"").join("").slice(0,2).toUpperCase();};
const formatDate=(value:unknown,withTime=true)=>{const date=new Date(safeText(value));if(Number.isNaN(date.getTime()))return "Not set";return new Intl.DateTimeFormat("en-AE",withTime?{dateStyle:"medium",timeStyle:"short"}:{dateStyle:"medium"}).format(date);};
const relativeTime=(value:unknown)=>{const date=new Date(safeText(value));if(Number.isNaN(date.getTime()))return "Unknown";const diff=Math.round((date.getTime()-Date.now())/60000);if(Math.abs(diff)<1)return "Just now";if(Math.abs(diff)<60)return diff<0?`${Math.abs(diff)}m ago`:`in ${diff}m`;const hours=Math.round(diff/60);if(Math.abs(hours)<24)return hours<0?`${Math.abs(hours)}h ago`:`in ${hours}h`;const days=Math.round(hours/24);return days<0?`${Math.abs(days)}d ago`:`in ${days}d`;};
const formatMoney=(value:number|null,currency="AED")=>value==null?"Budget not set":new Intl.NumberFormat("en-AE",{style:"currency",currency,maximumFractionDigits:0}).format(value);
const isClosed=(lead:Lead)=>lead.status==="Won"||lead.status==="Lost";
const isOverdue=(lead:Lead)=>Boolean(lead.followUp&&!isClosed(lead)&&new Date(lead.followUp).getTime()<Date.now());
const toLocalInput=(value:string|null)=>{if(!value)return "";const date=new Date(value);if(Number.isNaN(date.getTime()))return "";const offset=date.getTimezoneOffset();return new Date(date.getTime()-offset*60000).toISOString().slice(0,16);};
const toIso=(value:FormDataEntryValue|null)=>{const text=safeText(value);if(!text)return null;const date=new Date(text);return Number.isNaN(date.getTime())?null:date.toISOString();};
const taskGroup=(task:Task)=>{if(task.done)return "Completed";const due=new Date(task.dueAt);const now=new Date();const start=new Date(now.getFullYear(),now.getMonth(),now.getDate());const tomorrow=new Date(start.getTime()+86400000);if(due<now)return "Overdue";if(due<tomorrow)return "Today";return "Upcoming";};

export default function CrmApp(){
  const[user,setUser]=useState<User|null>(null);const[authLoading,setAuthLoading]=useState(true);const[systemError,setSystemError]=useState("");const[actionError,setActionError]=useState("");
  const[view,setView]=useState<View>("Dashboard");const[leads,setLeads]=useState<Lead[]>([]);const[leadTotal,setLeadTotal]=useState(0);const[tasks,setTasks]=useState<Task[]>([]);const[calendarEvents,setCalendarEvents]=useState<CalendarEvent[]>([]);const[employees,setEmployees]=useState<Employee[]>([]);const[sources,setSources]=useState<Option[]>([]);const[lostReasons,setLostReasons]=useState<Option[]>([]);const[company,setCompany]=useState(defaultCompany);const[rules,setRules]=useState(defaultRules);const[dashboard,setDashboard]=useState(emptyMetrics);const[reports,setReports]=useState(emptyReports);const[audit,setAudit]=useState<AuditItem[]>([]);
  const[selectedId,setSelectedId]=useState<number|null>(null);const[showNew,setShowNew]=useState(false);const[showTask,setShowTask]=useState(false);const[showEvent,setShowEvent]=useState(false);const[closing,setClosing]=useState<{lead:Lead;stage:"Won"|"Lost"}|null>(null);const[layout,setLayout]=useState<"board"|"list">("board");const[query,setQuery]=useState("");const[ownerFilter,setOwnerFilter]=useState("all");const[sourceFilter,setSourceFilter]=useState("all");const[statusFilter,setStatusFilter]=useState("all");const[priorityFilter,setPriorityFilter]=useState("all");const[attentionFilter,setAttentionFilter]=useState("all");const[leadPage,setLeadPage]=useState(1);const[note,setNote]=useState("");const[saving,setSaving]=useState("");const[toast,setToast]=useState("");const[duplicate,setDuplicate]=useState<Partial<Lead>|null>(null);const[pendingLead,setPendingLead]=useState<Record<string,unknown>|null>(null);
  const[templates,setTemplates]=useState<MessageTemplate[]>([]);
  const[selectedRecord,setSelectedRecord]=useState<Lead|null>(null);
  const[refreshTick,setRefreshTick]=useState(0);
  const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
  const selected=selectedRecord?.id===selectedId?selectedRecord:leads.find(lead=>lead.id===selectedId)??null;
  const activeEmployees=employees.filter(employee=>employee.isActive);
  const assignableEmployees=activeEmployees.filter(e=>!['Administrator','Manager'].includes(e.role)&&(user?.role!=='Sales Employee'||e.id===user.id));
  const canConfigure=user?.role==='Administrator'||user?.role==='Manager'||user?.role==='Reception';
  const canManage=user?.role==="Administrator"||user?.role==="Manager";

  const notify=useCallback((message:string)=>{setToast(message);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(""),2600);},[]);
  useEffect(()=>()=>{if(toastTimer.current)clearTimeout(toastTimer.current);},[]);

  const applyBootstrap=useCallback((data:Bootstrap)=>{setCsrfToken(data.csrfToken);setUser(data.user);setLeads(Array.isArray(data.leads?.items)?data.leads.items:[]);setLeadTotal(Number(data.leads?.total??0));setTasks(Array.isArray(data.tasks)?data.tasks:[]);setCalendarEvents(Array.isArray(data.calendarEvents)?data.calendarEvents:[]);setEmployees(Array.isArray(data.employees)?data.employees:[]);setSources(Array.isArray(data.sources)?data.sources:[]);setLostReasons(Array.isArray(data.lostReasons)?data.lostReasons:[]);setCompany(data.settings?.company??defaultCompany);setRules(data.settings?.attentionRules??defaultRules);setDashboard(data.dashboard??emptyMetrics);setReports(data.reports??emptyReports);setTemplates(data.settings.messageTemplates??[]);},[]);
  const reload=useCallback(async()=>{const data=await api<Bootstrap>("/api/bootstrap");applyBootstrap(data);setRefreshTick(t=>t+1);},[applyBootstrap]);
  useEffect(()=>{let mounted=true;(async()=>{try{const me=await api<{user:User;csrfToken:string}>("/api/auth/me");if(!mounted)return;setUser(me.user);setCsrfToken(me.csrfToken);await reload();}catch(error){if(!mounted)return;if(error instanceof ApiError&&error.status===401)setUser(null);else setSystemError("The CRM service or database file is unavailable. Ask the administrator to check the server status.");}finally{if(mounted)setAuthLoading(false);}})();return()=>{mounted=false};},[reload]);

  useEffect(()=>{if(!user)return;const controller=new AbortController();const timer=setTimeout(async()=>{try{const params=new URLSearchParams({page:String(leadPage)});if(query.trim())params.set("q",query.trim());if(ownerFilter!=="all")params.set("ownerId",ownerFilter);if(sourceFilter!=="all")params.set("sourceId",sourceFilter);if(statusFilter!=="all")params.set("status",statusFilter);if(priorityFilter!=="all")params.set("priority",priorityFilter);if(attentionFilter!=="all")params.set("attention",attentionFilter);const result=await api<{items:Lead[];total:number}>(`/api/leads?${params.toString()}`,{signal:controller.signal});setLeads(Array.isArray(result.items)?result.items:[]);setLeadTotal(Number(result.total??0));}catch(error){if(error instanceof DOMException&&error.name==="AbortError")return;setActionError(error instanceof Error?error.message:"Unable to load leads.");}},250);return()=>{clearTimeout(timer);controller.abort();};},[user,query,ownerFilter,sourceFilter,statusFilter,priorityFilter,attentionFilter,leadPage,refreshTick]);

  useEffect(()=>{if(!user)return;const timer=setInterval(()=>setRefreshTick(t=>t+1),15000);const onFocus=()=>setRefreshTick(t=>t+1);window.addEventListener('focus',onFocus);return()=>{clearInterval(timer);window.removeEventListener('focus',onFocus);};},[user?.id]);
  useEffect(()=>{if(!user)return;let stopped=false;void api<Bootstrap>('/api/bootstrap').then(data=>{if(stopped)return;setUser(data.user);setTasks(data.tasks);setCalendarEvents(data.calendarEvents);setEmployees(data.employees);setDashboard(data.dashboard);setReports(data.reports);setRules(data.settings.attentionRules);setTemplates(data.settings.messageTemplates??[]);}).catch(()=>{});return()=>{stopped=true;};},[refreshTick,user?.id]);
  const openLead=useCallback(async(id:number)=>{const lead=await api<Lead>(`/api/leads/${id}`);setSelectedRecord(lead);setSelectedId(id);},[]);
  useEffect(()=>{if(selectedId==null)return;let stopped=false;void api<Lead>(`/api/leads/${selectedId}`).then(lead=>{if(!stopped)setSelectedRecord(lead);}).catch(()=>{if(!stopped){setSelectedId(null);setSelectedRecord(null);}});return()=>{stopped=true;};},[selectedId,refreshTick]);
  useEffect(()=>{if(!user)return;const id=Number(new URLSearchParams(window.location.search).get('lead'));if(id>0){void openLead(id).catch(()=>setActionError('This lead is no longer available to your account.'));window.history.replaceState({},'',window.location.pathname);}},[user?.id,openLead]);
  useEffect(()=>{const onKey=(event:KeyboardEvent)=>{const key=normalizedKeyboardKey(event);if(key==="escape"){setSelectedId(null);setShowNew(false);setShowTask(false);setShowEvent(false);setClosing(null);return;}if(!key||isEditableShortcutTarget(event.target)||event.isComposing||event.defaultPrevented)return;if((event.ctrlKey||event.metaKey)&&key==="k"){event.preventDefault();setView("Leads");requestAnimationFrame(()=>document.getElementById("lead-search")?.focus());return;}if(key==="n"&&!event.ctrlKey&&!event.metaKey&&!event.altKey){event.preventDefault();setShowNew(true);}};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey);},[]);

  const handleError=(error:unknown,fallback="Unable to save your change.")=>{if(error instanceof ApiError&&error.status===401){setUser(null);setActionError("Your session expired. Sign in again.");return;}setActionError(error instanceof Error?error.message:fallback);};
  const signIn=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setSaving("login");setActionError("");const data=new FormData(event.currentTarget);try{const result=await api<{user:User;csrfToken:string}>("/api/auth/login",{method:"POST",body:JSON.stringify({email:safeText(data.get("email")),password:safeText(data.get("password"))})});setUser(result.user);setCsrfToken(result.csrfToken);await reload();}catch(error){handleError(error,"Unable to sign in.");}finally{setSaving("");}};
  const signOut=async()=>{try{await api<void>("/api/auth/logout",{method:"POST"});}catch{}setUser(null);setLeads([]);};
  const saveLead=async(lead:Lead,patch:Record<string,unknown>,message="Lead saved")=>{setSaving(`lead-${lead.id}`);setActionError("");try{await api(`/api/leads/${lead.id}`,{method:"PATCH",body:JSON.stringify({version:lead.version,...patch})});await reload();notify(message);}catch(error){handleError(error);}finally{setSaving("");}};
  const requestStage=(lead:Lead,stage:Stage)=>{if(stage===lead.status)return;if(stage==="Won"||stage==="Lost"){setClosing({lead,stage});return;}void saveLead(lead,{status:stage},`${lead.name} moved to ${stage}`);};
  const addNote=async()=>{if(!selected||!note.trim())return;setSaving("note");try{await api(`/api/leads/${selected.id}/notes`,{method:"POST",body:JSON.stringify({note:note.trim()})});setNote("");await reload();notify("Note saved to the timeline");}catch(error){handleError(error);}finally{setSaving("");}};
  const submitLead=async(payload:Record<string,unknown>)=>{setSaving("new-lead");setActionError("");try{const result=await api<{id:number}>("/api/leads",{method:"POST",body:JSON.stringify(payload)});setShowNew(false);setDuplicate(null);setPendingLead(null);await reload();setSelectedId(result.id);notify("Lead created and saved");}catch(error){if(error instanceof ApiError&&error.status===409&&error.duplicate){setDuplicate(error.duplicate as Partial<Lead>);setPendingLead(payload);}else handleError(error);}finally{setSaving("");}};
  const createLead=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);const budgetText=safeText(data.get("budget")).replace(/[^0-9.]/g,"");void submitLead({name:safeText(data.get("name")),phone:safeText(data.get("phone"))||null,email:safeText(data.get("email"))||null,sourceId:Number(data.get("sourceId")),interest:safeText(data.get("interest")),budget:budgetText?Number(budgetText):null,notes:safeText(data.get("notes")),assignedUserId:safeText(data.get("assignedUserId"))||null,priority:safeText(data.get("priority"))||"Normal",nextFollowUpAt:toIso(data.get("nextFollowUpAt"))});};
  const completeTask=async(task:Task)=>{setSaving(`task-${task.id}`);try{await api(`/api/tasks/${task.id}`,{method:"PATCH",body:JSON.stringify({version:task.version,isCompleted:!task.done})});await reload();notify(task.done?"Task reopened":"Task completed");}catch(error){handleError(error);}finally{setSaving("");}};
  const createTask=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);setSaving("new-task");try{await api("/api/tasks",{method:"POST",body:JSON.stringify({title:safeText(data.get("title")),leadId:Number(data.get("leadId"))||null,dueAt:toIso(data.get("dueAt")),assignedUserId:safeText(data.get("assignedUserId")),notes:safeText(data.get("notes"))})});setShowTask(false);await reload();notify("Task created");}catch(error){handleError(error);}finally{setSaving("");}};
  const createCalendarEvent=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);setSaving("new-event");try{await api("/api/calendar-events",{method:"POST",body:JSON.stringify({title:safeText(data.get("title")),leadId:Number(data.get("leadId")),eventType:safeText(data.get("eventType")),startsAt:toIso(data.get("startsAt")),endsAt:toIso(data.get("endsAt")),assignedUserId:safeText(data.get("assignedUserId"))})});setShowEvent(false);await reload();notify("Appointment scheduled and saved");}catch(error){handleError(error);}finally{setSaving("");}};
  const saveSettings=async(payload:Record<string,unknown>)=>{setSaving("settings");try{const result=await api<{company:CompanySettings;attentionRules:AttentionRules}>("/api/settings",{method:"PATCH",body:JSON.stringify(payload)});setCompany(result.company??company);setRules(result.attentionRules??rules);await reload();notify("Settings saved");}catch(error){handleError(error);}finally{setSaving("");}};
  const loadAudit=async(params="")=>{try{setAudit(await api<AuditItem[]>(`/api/audit?limit=200${params?`&${params}`:""}`));}catch(error){handleError(error);}};

  if(authLoading)return <LoadingScreen/>;
  if(!user)return <LoginScreen submit={signIn} busy={saving==="login"} error={actionError} systemError={systemError}/>;
  const navItems:{name:View;icon:string;count?:number}[]=[{name:"Dashboard",icon:"⌂"},{name:"Leads",icon:"◇",count:dashboard.active},{name:"Tasks",icon:"✓",count:tasks.filter(task=>!task.done).length},{name:"Calendar",icon:"□"},{name:"Reports",icon:"↗"}];
  const titles:Record<View,[string,string]>={Dashboard:["MY WORKSPACE",`Good ${new Date().getHours()<12?"morning":new Date().getHours()<17?"afternoon":"evening"}, ${user.displayName.split(" ")[0]??""}`],Leads:["SALES WORKSPACE","Leads pipeline"],Tasks:["MY WORKSPACE","Tasks"],Calendar:["MY WORKSPACE","Calendar"],Reports:["TEAM INSIGHTS","Reports"],Training:["TEAM LEARNING","Training"],Settings:["ADMINISTRATION","Settings"]};
  return <main className="app-shell"><aside className="sidebar"><button className="brand lead-brand" onClick={()=>setView("Dashboard")} aria-label="Lead CRM dashboard"><img className="brand-logo" src="/brand/crm-logo.svg" alt="Example Company"/><span className="brand-copy"><b>Lead</b><small>Lead CRM</small></span></button><nav>{navItems.filter(item=>item.name!=="Reports"||canManage).map(item=><button key={item.name} className={view===item.name?"active":""} onClick={()=>setView(item.name)}><i>{item.icon}</i><span>{item.name}</span>{item.count!==undefined&&<b>{item.count}</b>}</button>)}</nav><nav className="training-nav"><button className={view==="Training"?"active":""} onClick={()=>setView("Training")}><i>▤</i><span>Training</span></button></nav><div className="sidebar-spacer"/>{canConfigure&&<nav><button className={view==="Settings"?"active":""} onClick={()=>setView("Settings")}><i>⚙</i><span>Settings</span></button></nav>}<button className="profile-chip profile-button" onClick={signOut} title="Sign out"><span>{initials(user.displayName)}</span><div><strong>{user.displayName}</strong><small>{user.role}</small></div><i>↪</i></button></aside>
    <section className="workspace"><header className="topbar"><div><p className="eyebrow">{titles[view][0]}</p><h1>{titles[view][1]}</h1></div><div className="header-actions"><AssignmentAlerts user={user} open={openLead}/>{view==="Training"?<span className="training-header-label">Internal learning library</span>:<><span className={`save-state ${saving?"saving":""}`}>{saving?"Saving…":"All changes saved"}</span><button className="icon-button" aria-label="Search" onClick={()=>{setView("Leads");requestAnimationFrame(()=>document.getElementById("lead-search")?.focus())}}>⌕</button><button className="icon-button alert-dot" aria-label="Open attention dashboard" onClick={()=>setView("Dashboard")}>♢</button><button className="primary" onClick={()=>setShowNew(true)}>＋ Quick Add Lead</button></>}</div></header>
    {actionError&&<div className="inline-error"><span>!</span><p>{actionError}</p><button onClick={()=>setActionError("")}>Dismiss</button></div>}
    {view==="Dashboard"&&<DashboardView metrics={dashboard} leads={leads} tasks={tasks} openLead={id=>void openLead(id).catch(handleError)} filter={(attention)=>{setLeadPage(1);setAttentionFilter(attention);setView("Leads")}} go={setView}/>} 
    {view==='Leads'&&canManage&&<div className="export-filtered"><a href={`/api/export/leads.csv?${new URLSearchParams(Object.fromEntries(Object.entries({q:query,ownerId:ownerFilter,sourceId:sourceFilter,status:statusFilter,priority:priorityFilter,attention:attentionFilter}).filter(([,v])=>v&&v!=='all')))}`}>Export current results (CSV / Excel)</a></div>}
    {view==="Leads"&&<LeadsView leads={leads} total={leadTotal} page={leadPage} setPage={setLeadPage} layout={layout} setLayout={setLayout} query={query} setQuery={value=>{setLeadPage(1);setQuery(value)}} ownerFilter={ownerFilter} setOwnerFilter={value=>{setLeadPage(1);setOwnerFilter(value)}} sourceFilter={sourceFilter} setSourceFilter={value=>{setLeadPage(1);setSourceFilter(value)}} statusFilter={statusFilter} setStatusFilter={value=>{setLeadPage(1);setStatusFilter(value)}} priorityFilter={priorityFilter} setPriorityFilter={value=>{setLeadPage(1);setPriorityFilter(value)}} attentionFilter={attentionFilter} setAttentionFilter={value=>{setLeadPage(1);setAttentionFilter(value)}} employees={activeEmployees} sources={sources.filter(item=>item.is_active)} open={id=>void openLead(id).catch(handleError)} move={requestStage} add={()=>setShowNew(true)}/>} 
    {view==="Tasks"&&<TasksView tasks={tasks} currentUser={user} employees={activeEmployees} complete={completeTask} add={()=>setShowTask(true)} busy={saving}/>} 
    {view==="Calendar"&&<PersistentCalendarView leads={leads} tasks={tasks} scheduled={calendarEvents} open={id=>void openLead(id).catch(handleError)} add={()=>setShowEvent(true)}/>} 
    {view==="Reports"&&canManage&&<ProductionReportsView reports={reports} metrics={dashboard}/>} 
    {view==="Training"&&<TrainingView/>}
    {view==="Settings"&&canConfigure&&<ProductionSettingsView templates={templates} user={user} company={company} rules={rules} employees={employees} sources={sources} lostReasons={lostReasons} audit={audit} save={saveSettings} reload={reload} loadAudit={loadAudit} handleError={handleError} notify={notify}/>} 
    </section>
    {selected&&<LeadProfile key={selected.id} user={user} templates={templates} reload={reload} viewing={calendarEvents.find(e=>e.leadId===selected.id&&e.eventType==="viewing"&&Date.parse(e.startsAt)>Date.now())?.startsAt} lead={selected} employees={assignableEmployees} sources={sources.filter(item=>item.is_active)} currency={company.currency} lostReasons={lostReasons.filter(item=>item.is_active)} note={note} setNote={setNote} close={()=>setSelectedId(null)} addNote={addNote} save={patch=>saveLead(selected,patch)} requestStage={requestStage} addTask={()=>setShowTask(true)} busy={Boolean(saving)}/>} 
    {showNew&&<NewLeadModal user={user} close={()=>{setShowNew(false);setDuplicate(null);setPendingLead(null)}} submit={createLead} duplicate={duplicate} viewDuplicate={()=>{if(duplicate?.id){setShowNew(false);setSelectedId(Number(duplicate.id));}}} createAnyway={()=>pendingLead&&submitLead({...pendingLead,duplicateOverride:true})} employees={assignableEmployees} sources={sources.filter(item=>item.is_active)} busy={saving==="new-lead"} error={actionError}/>} 
    {showTask&&<NewTaskModal close={()=>setShowTask(false)} submit={createTask} leads={leads} employees={activeEmployees} defaultLeadId={selectedId} busy={saving==="new-task"}/>} 
    {showEvent&&<NewCalendarEventModal close={()=>setShowEvent(false)} submit={createCalendarEvent} leads={leads} employees={activeEmployees} defaultLeadId={selectedId} busy={saving==="new-event"}/>} 
    {closing&&<ClosureModal item={closing} reasons={lostReasons.filter(item=>item.is_active)} close={()=>setClosing(null)} submit={async payload=>{await saveLead(closing.lead,{status:closing.stage,...payload},`Lead marked ${closing.stage}`);setClosing(null);}} busy={Boolean(saving)}/>} 
    {toast&&<div className="toast" role="status">✓ {toast}</div>}</main>;
}

function LoadingScreen(){return <main className="auth-page"><div className="auth-card loading-card"><img src="/brand/crm-logo.svg" alt="Example Company"/><span className="loading-ring"/><h1>Opening Lead CRM</h1><p>Connecting securely to your workspace…</p></div></main>}
function LoginScreen({submit,busy,error,systemError}:{submit:(e:FormEvent<HTMLFormElement>)=>void;busy:boolean;error:string;systemError:string}){return <main className="auth-page"><section className="auth-brand"><img src="/brand/crm-logo.svg" alt="Example Company"/><div><p>LEAD CRM</p><h1>Every lead.<br/>One clear next step.</h1><span>A focused workspace for your sales team.</span></div></section><form className="auth-card" onSubmit={submit}><p className="eyebrow">SECURE INTERNAL CRM</p><h2>Welcome back</h2><span>Sign in with your company account.</span>{(error||systemError)&&<div className="login-error">{error||systemError}</div>}<label>Email address<input name="email" type="email" autoComplete="username" required autoFocus placeholder="you@example.com"/></label><label>Password<input name="password" type="password" autoComplete="current-password" required minLength={8}/></label><button className="primary" disabled={busy}>{busy?"Signing in…":"Sign in"}</button><small>Authorized Example Company employees only.</small></form></main>}

function DashboardView({metrics,leads,tasks,openLead,filter,go}:{metrics:DashboardMetrics;leads:Lead[];tasks:Task[];openLead:(id:number)=>void;filter:(x:string)=>void;go:(v:View)=>void}){const today=leads.filter(lead=>lead.followUp&&new Date(lead.followUp).toDateString()===new Date().toDateString());return <div className="page dashboard-page"><section className="attention-panel"><div className="panel-heading"><div><p className="eyebrow">START HERE</p><h2>Needs attention</h2></div><span>{metrics.neglected} items</span></div><div className="attention-grid"><AttentionButton count={metrics.overdue} label="Overdue follow-ups" detail="Contact these leads first" icon="!" danger action={()=>filter("overdue")}/><AttentionButton count={metrics.no_follow_up} label="Without follow-up" detail="Schedule the next step" icon="◇" action={()=>filter("no-follow-up")}/><AttentionButton count={metrics.neglected} label="Neglected leads" detail="Review all attention rules" icon="◷" danger action={()=>filter("neglected")}/><AttentionButton count={metrics.unassigned} label="Unassigned leads" detail="Assign an owner" icon="＋" action={()=>filter("unassigned")}/><AttentionButton count={metrics.tasksOverdue} label="Overdue tasks" detail="Complete or reschedule" icon="✓" danger action={()=>go("Tasks")}/></div></section><div className="dashboard-columns"><section className="surface today-panel"><div className="panel-heading"><div><p className="eyebrow">{new Intl.DateTimeFormat("en-AE",{weekday:"long",month:"short",day:"numeric"}).format(new Date()).toUpperCase()}</p><h2>Today</h2></div><button onClick={()=>go("Calendar")}>View calendar →</button></div><div className="today-stats"><div><b>{metrics.followUpsToday}</b><span>Follow-ups</span></div><div><b>{metrics.viewingsToday}</b><span>Viewings</span></div><div><b>{metrics.tasksToday}</b><span>Tasks</span></div></div><div className="agenda">{today.map(lead=><button key={lead.id} onClick={()=>openLead(lead.id)}><time>{formatDate(lead.followUp).split(", ").at(-1)}</time><span className="agenda-dot"/><div><strong>{lead.name}</strong><small>{lead.interest}</small></div><b>Open →</b></button>)}{today.length===0&&<Empty title="No follow-ups today" text="Everything scheduled for today is up to date."/>}</div></section><section className="surface pipeline-summary"><div className="panel-heading"><div><p className="eyebrow">CURRENT PIPELINE</p><h2>Team pipeline</h2></div><span>{metrics.active} active</span></div>{stages.slice(0,5).map(stage=><div className="summary-row" key={stage}><span className="status-dot"/><strong>{stage}</strong><div><i style={{width:`${Math.min(100,10+(metrics.stages[stage]??0)*8)}%`}}/></div><b>{metrics.stages[stage]??0}</b></div>)}<footer><span><b>{metrics.won}</b> Won</span><span><b>{metrics.conversionRate}%</b> Conversion</span></footer></section></div></div>}
function AttentionButton({count,label,detail,icon,danger,action}:{count:number;label:string;detail:string;icon:string;danger?:boolean;action:()=>void}){return <button onClick={action}><i className={danger?"danger":""}>{icon}</i><div><strong>{count}</strong><span>{label}</span><small>{detail}</small></div><b>→</b></button>}

function LeadsView(props:{leads:Lead[];total:number;page:number;setPage:(x:number)=>void;layout:"board"|"list";setLayout:(x:"board"|"list")=>void;query:string;setQuery:(x:string)=>void;ownerFilter:string;setOwnerFilter:(x:string)=>void;sourceFilter:string;setSourceFilter:(x:string)=>void;statusFilter:string;setStatusFilter:(x:string)=>void;priorityFilter:string;setPriorityFilter:(x:string)=>void;attentionFilter:string;setAttentionFilter:(x:string)=>void;employees:Employee[];sources:Option[];open:(id:number)=>void;move:(lead:Lead,stage:Stage)=>void;add:()=>void}){
  const clear=()=>{props.setQuery("");props.setOwnerFilter("all");props.setSourceFilter("all");props.setStatusFilter("all");props.setPriorityFilter("all");props.setAttentionFilter("all");props.setPage(1)};
  const filtered=Boolean(props.query||props.ownerFilter!=="all"||props.sourceFilter!=="all"||props.statusFilter!=="all"||props.priorityFilter!=="all"||props.attentionFilter!=="all");
  const pages=Math.max(1,Math.ceil(props.total/100));
  return <><div className="toolbar"><label className="search">⌕<input id="lead-search" value={props.query} onChange={e=>props.setQuery(e.target.value)} placeholder="Search name, phone, email, notes or interest…"/><kbd>⌘K</kbd></label><select value={props.statusFilter} onChange={e=>props.setStatusFilter(e.target.value)} aria-label="Status filter"><option value="all">All statuses</option>{stages.map(x=><option key={x}>{x}</option>)}</select><select value={props.ownerFilter} onChange={e=>props.setOwnerFilter(e.target.value)} aria-label="Employee filter"><option value="all">All employees</option><option value="unassigned">Unassigned</option>{props.employees.map(x=><option value={x.id} key={x.id}>{x.displayName}</option>)}</select><select value={props.sourceFilter} onChange={e=>props.setSourceFilter(e.target.value)} aria-label="Source filter"><option value="all">All sources</option>{props.sources.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select><select value={props.priorityFilter} onChange={e=>props.setPriorityFilter(e.target.value)} aria-label="Priority filter"><option value="all">All priorities</option>{priorities.map(item=><option key={item}>{item}</option>)}</select><select value={props.attentionFilter} onChange={e=>props.setAttentionFilter(e.target.value)} aria-label="Attention filter"><option value="all">All follow-ups</option><option value="overdue">Overdue</option><option value="today">Due today</option><option value="upcoming">Upcoming</option><option value="no-follow-up">No follow-up</option><option value="neglected">Neglected</option></select>{filtered&&<button className="clear-filter" onClick={clear}>Clear</button>}<div className="view-switch"><button className={props.layout==="board"?"selected":""} onClick={()=>props.setLayout("board")} aria-label="Board view">▦</button><button className={props.layout==="list"?"selected":""} onClick={()=>props.setLayout("list")} aria-label="List view">☷</button></div></div><div className="result-count"><span>Showing {props.leads.length} of {props.total} leads</span>{pages>1&&<span className="pagination"><button disabled={props.page<=1} onClick={()=>props.setPage(props.page-1)}>Previous</button><b>Page {props.page} of {pages}</b><button disabled={props.page>=pages} onClick={()=>props.setPage(props.page+1)}>Next</button></span>}</div>{props.layout==="board"?<div className="pipeline">{stages.map(stage=><section className="stage" key={stage} onDragOver={e=>e.preventDefault()} onDrop={e=>{const id=Number(e.dataTransfer.getData("leadId"));const lead=props.leads.find(item=>item.id===id);if(lead)props.move(lead,stage)}}><div className="stage-title"><span className={`status-dot ${safeLower(stage).replaceAll(" ","-").replace("/","")}`}/><h2>{stage}</h2><b>{props.leads.filter(lead=>lead.status===stage).length}</b></div><div className="stage-cards">{props.leads.filter(lead=>lead.status===stage).map(lead=><LeadCard key={lead.id} lead={lead} open={()=>props.open(lead.id)}/>)}<button className="add-card" onClick={props.add}>＋ Add lead</button></div></section>)}</div>:<LeadTable leads={props.leads} open={props.open}/>}</>
}
function LeadCard({lead,open}:{lead:Lead;open:()=>void}){const flag=lead.status==="Won"?"WON":lead.status==="Lost"?"LOST":isOverdue(lead)?"OVERDUE":lead.owner==="Unassigned"?"UNASSIGNED":!lead.followUp?"NO FOLLOW-UP":lead.priority==="Urgent"?"URGENT":lead.priority==="High"?"HIGH PRIORITY":"ON TRACK";return <article className={`lead-card ${lead.stale?"stale-lead":""}`} draggable onDragStart={e=>e.dataTransfer.setData("leadId",String(lead.id))} onClick={open} tabIndex={0} onKeyDown={e=>e.key==="Enter"&&open()}><div className={`flag ${safeLower(flag).replaceAll(" ","-")}`}>{lead.stale?"NO UPDATE FOR 3 DAYS":flag}</div><h3>{lead.name}</h3><p className="interest">{lead.interest}</p><strong className="budget">{formatMoney(lead.budget)}</strong><div className="owner-row"><span>{initials(lead.owner)}</span><p><small>Assigned to</small>{lead.owner}</p></div><div className={`follow-row ${isOverdue(lead)?"is-overdue":""}`}><p><small>Next follow-up</small>{lead.followUp?formatDate(lead.followUp):"No follow-up"}</p><span>↗</span></div><footer><span>{lead.source}</span><small>Activity · {relativeTime(lead.lastActivityAt)}</small></footer></article>}
function LeadTable({leads,open}:{leads:Lead[];open:(id:number)=>void}){const[sort,setSort]=useState<keyof Lead>("name");const[ascending,setAscending]=useState(true);const rows=useMemo(()=>[...leads].sort((a,b)=>String(a[sort]??"").localeCompare(String(b[sort]??""))*(ascending?1:-1)),[leads,sort,ascending]);const header=(label:string,key:keyof Lead)=><button onClick={()=>{if(sort===key)setAscending(!ascending);else{setSort(key);setAscending(true)}}}>{label}{sort===key?(ascending?" ↑":" ↓"):""}</button>;return <div className="table-wrap"><table><thead><tr><th>{header("Lead","name")}</th><th>Phone</th><th>{header("Interest","interest")}</th><th>{header("Source","source")}</th><th>{header("Status","status")}</th><th>{header("Assigned To","owner")}</th><th>{header("Priority","priority")}</th><th>{header("Next Follow-up","followUp")}</th><th>{header("Last Activity","lastActivityAt")}</th></tr></thead><tbody>{rows.map(lead=><tr className={lead.stale?"stale-lead":""} key={lead.id} onClick={()=>open(lead.id)}><td><strong>{lead.name}</strong><small>{lead.reference}</small>{lead.stale&&<small className="stale-label">No update for 3 days</small>}</td><td>{lead.phone||"—"}</td><td>{lead.interest}</td><td><span className="source-pill">{lead.source}</span></td><td><span className="status-pill">{lead.status}</span></td><td>{lead.owner}</td><td><span className={`priority ${safeLower(lead.priority)}`}>{lead.priority}</span></td><td className={isOverdue(lead)?"red":""}>{lead.followUp?formatDate(lead.followUp):"Not scheduled"}</td><td>{relativeTime(lead.lastActivityAt)}</td></tr>)}</tbody></table>{!rows.length&&<Empty title="No leads found" text="Clear a filter or try another search."/>}</div>}

function LeadProfile({user,templates,reload,viewing,lead,employees,sources,currency,lostReasons,note,setNote,close,addNote,save,requestStage,addTask,busy}:{user:User;templates:MessageTemplate[];reload:()=>Promise<void>;viewing?:string;lead:Lead;employees:Employee[];sources:Option[];currency:string;lostReasons:Option[];note:string;setNote:(x:string)=>void;close:()=>void;addNote:()=>void;save:(p:Record<string,unknown>)=>Promise<void>;requestStage:(lead:Lead,stage:Stage)=>void;addTask:()=>void;busy:boolean}){const[editing,setEditing]=useState(false);const phoneTarget=normalizePhone(lead.phone);const submitEdit=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);const budget=safeText(data.get("budget")).replace(/[^0-9.]/g,"");void save({name:safeText(data.get("name")),phone:safeText(data.get("phone"))||null,email:safeText(data.get("email"))||null,sourceId:Number(data.get("sourceId")),interest:safeText(data.get("interest")),budget:budget?Number(budget):null,notes:safeText(data.get("notes"))}).then(()=>setEditing(false));};return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><aside className="lead-profile" role="dialog" aria-modal="true" aria-label={`${lead.name} profile`}><header className="profile-header"><button className="close" onClick={close} aria-label="Close profile">×</button><div className="lead-avatar">{initials(lead.name)}</div><div><span className="profile-status">{lead.status}</span><h2>{lead.name}</h2><p>{lead.reference} · {lead.interest}</p></div><Communications lead={lead} templates={templates} user={user} reload={reload} viewing={viewing}/></header>{(isOverdue(lead)||lead.owner==="Unassigned"||(!lead.followUp&&!isClosed(lead)))&&<div className="profile-warning"><b>! Needs attention</b><span>{isOverdue(lead)?`Follow-up was due ${formatDate(lead.followUp)}`:lead.owner==="Unassigned"?"This active lead has no owner.":"No next follow-up is scheduled."}</span></div>}<div className="profile-body"><div className="profile-main">{editing?<form className="info-card form-grid profile-edit" onSubmit={submitEdit}><div className="section-heading wide"><h3>Edit lead details</h3><button type="button" onClick={()=>setEditing(false)}>Cancel</button></div><label>Name *<input name="name" defaultValue={lead.name} required/></label><label>Phone<input name="phone" defaultValue={lead.phone}/></label><label>Email<input name="email" type="email" defaultValue={lead.email}/></label><label>Source<select name="sourceId" defaultValue={lead.sourceId}>{sources.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="wide">Interest *<input name="interest" defaultValue={lead.interest} required/></label><label>Budget<input name="budget" type="number" min="0" defaultValue={lead.budget??""}/></label><label className="wide">Notes<textarea name="notes" defaultValue={lead.notes}/></label><div className="wide form-actions"><button type="button" onClick={()=>setEditing(false)}>Cancel</button><button className="primary" disabled={busy}>Save details</button></div></form>:<><section className="info-card"><div className="section-heading"><h3>Contact</h3><button onClick={()=>setEditing(true)}>Edit lead</button></div><div className="detail-grid"><label>PHONE<strong>{lead.phone||"Not provided"}</strong></label><label>EMAIL<strong>{lead.email||"Not provided"}</strong></label></div></section><section className="info-card"><div className="section-heading"><h3>Lead information</h3><button onClick={()=>setEditing(true)}>Edit</button></div><div className="detail-grid two"><label>SOURCE<strong>{lead.source}</strong></label><label>BUDGET<strong>{formatMoney(lead.budget,currency)}</strong></label><label className="wide">INTEREST<strong>{lead.interest}</strong></label><label className="wide">NOTES<p>{lead.notes||"No notes added."}</p></label></div><div className="meta-row"><span>Created {formatDate(lead.createdAt,false)}</span><span>Created by {lead.createdBy}</span></div></section>{isClosed(lead)&&<section className="info-card closure-details"><div className="section-heading"><h3>{lead.status==="Won"?"Won details":"Lost details"}</h3><span>{lead.status==="Won"?"Deal closed":"Lead closed"}</span></div><div className="detail-grid two">{lead.status==="Won"?<><label>CLOSING DATE<strong>{lead.wonAt?formatDate(lead.wonAt):"Recorded"}</strong></label><label>DEAL AMOUNT<strong>{formatMoney(lead.wonAmount,currency)}</strong></label><label className="wide">PRODUCT / SERVICE / PROPERTY<strong>{lead.interest}</strong></label><label className="wide">CLOSING NOTE<p>{lead.closingNote||"No closing note."}</p></label></>:<><label>LOST DATE<strong>{lead.lostAt?formatDate(lead.lostAt):"Recorded"}</strong></label><label>LOST REASON<strong>{lead.lostReason||"Not recorded"}</strong></label><label className="wide">LOST NOTE<p>{lead.lostNote||"No additional note."}</p></label></>}</div></section>}</>}<RequirementsPanel lead={lead} reload={reload}/><section className="info-card quick-note"><div className="section-heading"><h3>＋ Add note</h3><span>Saved permanently to history</span></div><textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={5000} placeholder="Write a quick update from your call or meeting…"/><div><small>{note.length}/5000</small><button className="primary small" disabled={!note.trim()||busy} onClick={addNote}>Save note</button></div></section><section className="timeline-section"><div className="section-heading"><h3>History</h3><span>Chronological activity</span></div><div className="timeline">{lead.timeline.map((item,index)=><div className="timeline-item" key={`${item.time}-${index}`}><span className={`timeline-icon ${safeLower(item.type)}`}>{item.type==="call"?"☎":item.type==="email"?"✉":item.type==="whatsapp"?"◉":item.type==="status"?"↗":item.type==="task"?"✓":item.type==="note"?"≡":"•"}</span><div><time>{formatDate(item.time)}</time><strong>{item.title}</strong>{item.detail&&<p>{item.detail}</p>}</div>{item.author&&<b>{initials(item.author)}</b>}</div>)}{!lead.timeline.length&&<Empty title="No activity yet" text="Notes, calls, tasks, and status changes appear here."/>}</div></section></div><aside className="management-card"><h3>Management</h3><label>ASSIGNED EMPLOYEE<select value={lead.assignedUserId??""} onChange={e=>void save({assignedUserId:e.target.value||null})} disabled={busy}><option value="">Unassigned</option>{lead.assignedUserId&&!employees.some(e=>e.id===lead.assignedUserId)&&<option value={lead.assignedUserId}>{lead.owner} (current owner)</option>}{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select></label><label>STATUS<select value={lead.status} onChange={e=>requestStage(lead,e.target.value as Stage)} disabled={busy}>{stages.map(item=><option key={item}>{item}</option>)}</select></label><label>PRIORITY<select value={lead.priority} onChange={e=>void save({priority:e.target.value})} disabled={busy}>{priorities.map(item=><option key={item}>{item}</option>)}</select></label><label>NEXT FOLLOW-UP<input type="datetime-local" value={toLocalInput(lead.followUp)} disabled={busy||isClosed(lead)} onChange={e=>void save({nextFollowUpAt:e.target.value?new Date(e.target.value).toISOString():null})}/></label><div className="management-meta"><span><small>LAST INTERACTION</small>{relativeTime(lead.lastActivityAt)}</span><span><small>LEAD OWNER</small>{lead.owner}</span></div><button className="add-task-button" onClick={addTask}>＋ Add task</button></aside></div></aside></div>}

function NewLeadModal({user,close,submit,duplicate,viewDuplicate,createAnyway,employees,sources,busy,error}:{user:User;close:()=>void;submit:(e:FormEvent<HTMLFormElement>)=>void;duplicate:Partial<Lead>|null;viewDuplicate:()=>void;createAnyway:()=>void;employees:Employee[];sources:Option[];busy:boolean;error:string}){const[more,setMore]=useState(false);const[self,setSelf]=useState(false);return <div className="modal-backdrop centered" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="new-lead-modal" onSubmit={submit}><header><div><p className="eyebrow">QUICK CREATE</p><h2>Quick Add Lead</h2><span>Add the essentials now. Complete the profile later.</span></div><button type="button" className="close" onClick={close}>×</button></header>{duplicate&&<div className="duplicate-warning"><b>Possible duplicate lead</b><p>A lead with this phone number or email already exists.</p><div><span>{initials(duplicate.name)}</span><p><strong>{duplicate.name}</strong>Assigned to {duplicate.owner??"Unassigned"} · {duplicate.status}</p><button type="button" onClick={viewDuplicate}>View existing</button></div></div>}{error&&!duplicate&&<div className="form-error">{error}</div>}<div className="form-grid"><label>Full name *<input required name="name" autoFocus/></label><label>Phone *<input name="phone" required placeholder="+971 50 123 4567"/></label>{more&&<label>Email<input name="email" type="email"/></label>}<label>Lead source *<select required name="sourceId" defaultValue=""><option value="" disabled>Select source</option>{sources.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="wide">Product, service or property *<input required name="interest"/></label><label>Assigned employee *{self?<><input type="hidden" name="assignedUserId" value={user.id}/><span className="self-owner-note">Assigned to you</span></>:<select name="assignedUserId" required defaultValue={user.role==="Sales Employee"?user.id:""}><option value="" disabled>Select employee</option>{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select>}</label>{more&&<><label>Budget<input name="budget" type="number" min="0"/></label><label>Priority<select name="priority" defaultValue="Normal">{priorities.map(item=><option key={item}>{item}</option>)}</select></label><label>Next follow-up<input name="nextFollowUpAt" type="datetime-local"/></label><label className="wide">Notes<textarea name="notes"/></label></>}</div>{user.role==="Manager"&&<label className="quick-self toggle-label"><input type="checkbox" checked={self} onChange={e=>setSelf(e.target.checked)}/> Assign this new lead to me</label>}<div className="quick-add-toggle"><button type="button" onClick={()=>setMore(!more)}>{more?"Hide additional details":"＋ Additional details (optional)"}</button></div><footer><span>Press <kbd>N</kbd> anywhere to open this form</span><div><button type="button" onClick={close}>Cancel</button>{duplicate&&<button type="button" onClick={createAnyway} disabled={busy}>Create anyway</button>}<button className="primary" type="submit" disabled={busy}>{busy?"Saving…":"Create lead"}</button></div></footer></form></div>}
function NewTaskModal({close,submit,leads,employees,defaultLeadId,busy}:{close:()=>void;submit:(e:FormEvent<HTMLFormElement>)=>void;leads:Lead[];employees:Employee[];defaultLeadId:number|null;busy:boolean}){return <div className="modal-backdrop centered" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="new-lead-modal compact-modal" onSubmit={submit}><header><div><p className="eyebrow">NEXT ACTION</p><h2>New task</h2></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-grid"><label className="wide">Task *<input name="title" required autoFocus placeholder="Call customer"/></label><label>Related lead<select name="leadId" defaultValue={defaultLeadId??""}><option value="">No related lead</option>{leads.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>Assigned employee *<select name="assignedUserId" required defaultValue=""><option value="" disabled>Select employee</option>{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select></label><label>Due date and time *<input name="dueAt" type="datetime-local" required/></label><label className="wide">Notes<textarea name="notes"/></label></div><footer><span>Tasks appear on the lead timeline.</span><div><button type="button" onClick={close}>Cancel</button><button className="primary" disabled={busy}>{busy?"Saving…":"Create task"}</button></div></footer></form></div>}
function ClosureModal({item,reasons,close,submit,busy}:{item:{lead:Lead;stage:"Won"|"Lost"};reasons:Option[];close:()=>void;submit:(p:Record<string,unknown>)=>Promise<void>;busy:boolean}){const won=item.stage==="Won";const handle=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);void submit(won?{wonAmount:Number(data.get("wonAmount"))||null,closingNote:safeText(data.get("closingNote"))}:{lostReasonId:Number(data.get("lostReasonId")),lostNote:safeText(data.get("lostNote"))});};return <div className="modal-backdrop centered"><form className="new-lead-modal compact-modal" onSubmit={handle}><header><div><p className="eyebrow">CLOSE LEAD</p><h2>Mark {item.lead.name} {item.stage}</h2></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-grid">{won?<><label>Deal amount<input name="wonAmount" type="number" min="0"/></label><label className="wide">Closing note<textarea name="closingNote" placeholder="What was agreed?"/></label></>:<><label className="wide">Lost reason *<select name="lostReasonId" required defaultValue=""><option value="" disabled>Select a reason</option>{reasons.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="wide">Optional note<textarea name="lostNote"/></label></>}</div><footer><span>Follow-up alerts stop after closure.</span><div><button type="button" onClick={close}>Cancel</button><button className="primary" disabled={busy}>Confirm {item.stage}</button></div></footer></form></div>}

function TasksView({tasks,currentUser,employees,complete,add,busy}:{tasks:Task[];currentUser:User;employees:Employee[];complete:(task:Task)=>void;add:()=>void;busy:string}){const[mine,setMine]=useState(false);const[employee,setEmployee]=useState("all");const visible=tasks.filter(task=>(!mine||task.assignedUserId===currentUser.id)&&(employee==="all"||task.assignedUserId===employee));return <div className="page"><div className="sub-toolbar"><div className="segmented"><button className={!mine?"active":""} onClick={()=>setMine(false)}>All tasks</button><button className={mine?"active":""} onClick={()=>setMine(true)}>My tasks</button></div><select value={employee} onChange={e=>setEmployee(e.target.value)}><option value="all">All employees</option>{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select><button className="primary" onClick={add}>＋ New task</button></div><div className="task-groups">{["Overdue","Today","Upcoming","Completed"].map(group=>{const grouped=visible.filter(task=>taskGroup(task)===group);return <section className="task-group" key={group}><header><h2>{group}</h2><span>{grouped.length}</span></header>{grouped.map(task=><article className={task.done?"done":""} key={task.id}><button className="check" onClick={()=>complete(task)} disabled={busy===`task-${task.id}`} aria-label={task.done?"Reopen task":"Complete task"}>{task.done?"✓":""}</button><div><strong>{task.title}</strong><span>{task.lead}</span></div><time className={group==="Overdue"?"red":""}>{formatDate(task.dueAt)}</time><span className="task-owner">{initials(task.owner)}<small>{task.owner}</small></span></article>)}{!grouped.length&&<Empty title={`No ${safeLower(group)} tasks`} text={group==="Overdue"?"Nothing is currently overdue.":"No tasks in this group."}/>}</section>})}</div></div>}
function CalendarView({leads,tasks,open}:{leads:Lead[];tasks:Task[];open:(id:number)=>void}){const[mode,setMode]=useState<"Day"|"Week"|"Month">("Month");const[cursor,setCursor]=useState(new Date());const events=[...leads.filter(lead=>lead.followUp).map(lead=>({id:`l${lead.id}`,at:new Date(lead.followUp!),title:`Follow-up · ${lead.name}`,leadId:lead.id,type:"follow"})),...tasks.map(task=>({id:`t${task.id}`,at:new Date(task.dueAt),title:`Task · ${task.title}`,leadId:task.leadId,type:"task"}))].filter(item=>!Number.isNaN(item.at.getTime()));const start=new Date(cursor.getFullYear(),cursor.getMonth(),1);const offset=(start.getDay()+6)%7;const days=Array.from({length:42},(_,i)=>new Date(cursor.getFullYear(),cursor.getMonth(),i-offset+1));const periodEvents=events.filter(event=>mode==="Day"?event.at.toDateString()===cursor.toDateString():mode==="Week"?Math.abs(event.at.getTime()-cursor.getTime())<4*86400000:event.at.getMonth()===cursor.getMonth()&&event.at.getFullYear()===cursor.getFullYear());return <div className="page"><div className="calendar-toolbar"><div className="segmented">{(["Day","Week","Month"] as const).map(item=><button key={item} className={mode===item?"active":""} onClick={()=>setMode(item)}>{item}</button>)}</div><div><button onClick={()=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+(mode==="Month"?-1:0),cursor.getDate()-(mode==="Week"?7:mode==="Day"?1:0)))}>‹</button><h2>{mode==="Month"?new Intl.DateTimeFormat("en-AE",{month:"long",year:"numeric"}).format(cursor):formatDate(cursor.toISOString(),false)}</h2><button onClick={()=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+(mode==="Month"?1:0),cursor.getDate()+(mode==="Week"?7:mode==="Day"?1:0)))}>›</button></div><button onClick={()=>setCursor(new Date())}>Today</button></div>{mode==="Month"?<div className="calendar-grid">{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(day=><b className="weekday" key={day}>{day}</b>)}{days.map(day=><div className={`calendar-day ${day.toDateString()===new Date().toDateString()?"today":""} ${day.getMonth()!==cursor.getMonth()?"muted":""}`} key={day.toISOString()}><span>{day.getDate()}</span>{events.filter(event=>event.at.toDateString()===day.toDateString()).slice(0,3).map(event=><button key={event.id} className={event.type==="task"?"task-event":""} onClick={()=>event.leadId&&open(event.leadId)}><i/>{event.at.toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})} · {event.title}</button>)}</div>)}</div>:<div className="surface calendar-agenda">{periodEvents.sort((a,b)=>a.at.getTime()-b.at.getTime()).map(event=><button key={event.id} onClick={()=>event.leadId&&open(event.leadId)}><time>{formatDate(event.at.toISOString())}</time><i className={event.type}/><strong>{event.title}</strong><span>Open →</span></button>)}{!periodEvents.length&&<Empty title="No calendar events" text="Follow-ups and tasks appear here automatically."/>}</div>}</div>}
function ReportsView({reports,metrics}:{reports:ReportData;metrics:DashboardMetrics}){const max=Math.max(1,...reports.sources.map(item=>item.count));const stageMax=Math.max(1,...stages.map(stage=>metrics.stages[stage]??0));return <div className="page reports-page"><div className="report-cards"><div><span>ACTIVE LEADS</span><strong>{metrics.active}</strong><small>{metrics.unassigned} unassigned</small></div><div><span>WON</span><strong>{metrics.won}</strong><small>{metrics.lost} lost</small></div><div><span>CONVERSION RATE</span><strong>{metrics.conversionRate}%</strong><small>Based on closed leads</small></div><div><span>OVERDUE FOLLOW-UPS</span><strong>{metrics.overdue}</strong><small>Requires attention</small></div></div><div className="report-grid"><section className="surface"><div className="panel-heading"><div><p className="eyebrow">ACQUISITION</p><h2>Lead sources</h2></div><a className="text-link" href="/api/export/leads.csv">Export CSV</a></div><div className="bars">{reports.sources.map(item=><div key={item.name}><span>{item.name}</span><div><i style={{width:`${Math.max(3,item.count/max*100)}%`}}/></div><b>{item.count}</b></div>)}</div></section><section className="surface"><div className="panel-heading"><div><p className="eyebrow">TEAM</p><h2>Employee performance</h2></div></div><div className="workload">{reports.employees.map(item=><div key={item.id}><span className="avatar-small">{initials(item.display_name)}</span><div><strong>{item.display_name}</strong><small>{item.assigned} assigned · {item.contacted} contacted · {item.active} active · {item.overdue} overdue · {item.won} won · {item.lost} lost</small></div><b>{item.conversionRate}%</b></div>)}</div></section><section className="surface pipeline-report"><div className="panel-heading"><div><p className="eyebrow">PIPELINE</p><h2>Leads by stage</h2></div></div><div className="stage-bars">{stages.map(stage=><div key={stage}><div style={{height:`${45+((metrics.stages[stage]??0)/stageMax)*110}px`}}>{metrics.stages[stage]??0}</div><span>{stage}</span></div>)}</div></section><section className="surface pipeline-report"><div className="panel-heading"><div><p className="eyebrow">LOST LEADS</p><h2>Lost reasons</h2></div></div><div className="lost-grid">{reports.lostReasons.map(item=><div key={item.name}><span>{item.name}</span><b>{item.count}</b></div>)}</div></section></div></div>}

function SettingsView({user,company,rules,employees,audit,save,reload,loadAudit,handleError,notify}:{user:User;company:CompanySettings;rules:AttentionRules;employees:Employee[];audit:AuditItem[];save:(p:Record<string,unknown>)=>Promise<void>;reload:()=>Promise<void>;loadAudit:()=>Promise<void>;handleError:(e:unknown)=>void;notify:(x:string)=>void}){const[tab,setTab]=useState<"Company"|"Employees"|"Attention rules"|"Audit log">("Company");const[employeeModal,setEmployeeModal]=useState<Employee|"new"|null>(null);const[deactivate,setDeactivate]=useState<Employee|null>(null);useEffect(()=>{if(tab==="Audit log")void loadAudit();},[tab]);const saveEmployee=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);const payload={firstName:safeText(data.get("firstName")),lastName:safeText(data.get("lastName")),displayName:safeText(data.get("displayName")),email:safeText(data.get("email")),phone:safeText(data.get("phone"))||null,role:safeText(data.get("role")) as Role,...(employeeModal==="new"?{password:safeText(data.get("password"))}:{version:(employeeModal as Employee).version})};try{await api(employeeModal==="new"?"/api/employees":`/api/employees/${(employeeModal as Employee).id}`,{method:employeeModal==="new"?"POST":"PATCH",body:JSON.stringify(payload)});setEmployeeModal(null);await reload();notify(employeeModal==="new"?"Employee added":"Employee updated");}catch(error){handleError(error);}};const deactivateNow=async(employee:Employee,transferToUserId?:string)=>{try{await api(`/api/employees/${employee.id}/deactivate`,{method:"POST",body:JSON.stringify({transferToUserId:transferToUserId||undefined})});setDeactivate(null);await reload();notify("Employee deactivated safely");}catch(error){handleError(error);}};const reactivate=async(employee:Employee)=>{try{await api(`/api/employees/${employee.id}`,{method:"PATCH",body:JSON.stringify({version:employee.version,isActive:true})});await reload();notify("Employee reactivated");}catch(error){handleError(error);}};return <div className="page settings-page"><div className="settings-nav">{(["Company","Employees","Attention rules","Audit log"] as const).map(item=><button className={tab===item?"active":""} key={item} onClick={()=>setTab(item)}>{item}</button>)}</div><div className="settings-content">{tab==="Company"&&<form className="surface" onSubmit={event=>{event.preventDefault();const data=new FormData(event.currentTarget);void save({company:{companyName:safeText(data.get("companyName")),timezone:safeText(data.get("timezone")),currency:safeText(data.get("currency")).toUpperCase(),internalUrl:safeText(data.get("internalUrl"))}})}}><div className="panel-heading"><div><p className="eyebrow">WORKSPACE</p><h2>Company settings</h2></div><span>Saved to the CRM database</span></div><div className="settings-form"><label>Company name<input name="companyName" defaultValue={company.companyName} required/></label><label>Timezone<select name="timezone" defaultValue={company.timezone}><option>Asia/Dubai</option><option>UTC</option></select></label><label>Default currency<input name="currency" defaultValue={company.currency} maxLength={3} required/></label><label>Internal CRM address<input name="internalUrl" defaultValue={company.internalUrl}/></label><button className="primary">Save company settings</button></div></form>}{tab==="Attention rules"&&<form className="surface rules-card" onSubmit={event=>{event.preventDefault();const data=new FormData(event.currentTarget);void save({attentionRules:{highlightStale:data.get("highlightStale")==="on",newLeadHours:Number(data.get("newLeadHours")),inactiveLeadHours:Number(data.get("inactiveLeadHours")),flagMissingFollowUp:data.get("flagMissingFollowUp")==="on",flagUnassigned:data.get("flagUnassigned")==="on"}})}}><div className="panel-heading"><div><p className="eyebrow">ACCOUNTABILITY</p><h2>Lead attention rules</h2></div><span>Transparent rules only</span></div><label><div><strong>Red cards after 3 days</strong><small>No recorded call, message, note or status update for 72 hours</small></div><input name="highlightStale" type="checkbox" defaultChecked={rules.highlightStale!==false}/></label><label><div><strong>New lead untouched</strong><small>Warn when a New lead has no contact activity</small></div><span>After <input name="newLeadHours" type="number" min="1" max="720" defaultValue={rules.newLeadHours}/> hours</span></label><label><div><strong>Active lead inactive</strong><small>Warn when no activity is recorded</small></div><span>After <input name="inactiveLeadHours" type="number" min="1" max="2160" defaultValue={rules.inactiveLeadHours}/> hours</span></label><label><div><strong>Missing next follow-up</strong><small>Flag active leads without a scheduled next step</small></div><input name="flagMissingFollowUp" type="checkbox" defaultChecked={rules.flagMissingFollowUp}/></label><label><div><strong>Unassigned active lead</strong><small>Always show in the manager attention panel</small></div><input name="flagUnassigned" type="checkbox" defaultChecked={rules.flagUnassigned}/></label><button className="primary settings-save">Save attention rules</button></form>}{tab==="Employees"&&<section className="surface"><div className="panel-heading"><div><p className="eyebrow">TEAM ACCESS</p><h2>Sales employees</h2></div><button className="primary small" onClick={()=>setEmployeeModal("new")}>＋ Add employee</button></div><div className="employee-table">{employees.map(employee=><article className={!employee.isActive?"inactive":""} key={employee.id}><span className="avatar-small">{initials(employee.displayName)}</span><div><strong>{employee.displayName}</strong><small>{employee.email} · {employee.role}</small></div><span className={`employee-state ${employee.isActive?"active":""}`}>{employee.isActive?"Active":"Inactive"}</span><span><b>{employee.activeLeads}</b><small>active leads</small></span><span><b>{employee.overdueLeads}</b><small>overdue</small></span><div className="row-actions"><button onClick={()=>setEmployeeModal(employee)}>Edit</button>{employee.isActive&&employee.id!==user.id?<button onClick={()=>employee.activeLeads?setDeactivate(employee):void deactivateNow(employee)}>Deactivate</button>:!employee.isActive?<button onClick={()=>void reactivate(employee)}>Reactivate</button>:null}</div></article>)}</div></section>}{tab==="Audit log"&&<section className="surface"><div className="panel-heading"><div><p className="eyebrow">APPEND-ONLY HISTORY</p><h2>Audit log</h2></div>{user.role!=="Reception"&&<a className="text-link" href="/api/export/audit.csv">Export CSV</a>}</div><div className="audit-list">{audit.map(item=><article key={item.id}><time>{formatDate(item.timestamp)}</time><div><strong>{item.user_name} · {item.action}</strong><p>{item.entity_type} {item.entity_id}{item.field_changed?` · ${item.field_changed}`:""}</p>{(item.old_value||item.new_value)&&<small>{item.old_value??"—"} → {item.new_value??"—"}</small>}</div></article>)}{!audit.length&&<Empty title="No audit history" text="Business changes will appear here."/>}</div></section>}</div>{employeeModal&&<EmployeeModal item={employeeModal} close={()=>setEmployeeModal(null)} submit={saveEmployee}/>} {deactivate&&<DeactivateModal employee={deactivate} employees={employees.filter(item=>item.isActive&&item.id!==deactivate.id)} close={()=>setDeactivate(null)} submit={id=>deactivateNow(deactivate,id)}/>}</div>}
function EmployeeModal({item,close,submit}:{item:Employee|"new";close:()=>void;submit:(e:FormEvent<HTMLFormElement>)=>void}){const isNew=item==="new";return <div className="modal-backdrop centered"><form className="new-lead-modal compact-modal" onSubmit={submit}><header><div><p className="eyebrow">TEAM MEMBER</p><h2>{isNew?"Add employee":"Edit employee"}</h2></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-grid"><label>First name *<input name="firstName" required defaultValue={isNew?"":item.firstName}/></label><label>Last name *<input name="lastName" required defaultValue={isNew?"":item.lastName}/></label><label className="wide">Display name *<input name="displayName" required defaultValue={isNew?"":item.displayName}/></label><label>Email *<input name="email" type="email" required defaultValue={isNew?"":item.email}/></label><label>Phone<input name="phone" defaultValue={isNew?"":item.phone}/></label><label>Role<select name="role" defaultValue={isNew?"Sales Employee":item.role}><option>Administrator</option><option>Manager</option><option>Sales Employee</option></select></label>{isNew&&<label className="wide">Temporary password *<input name="password" type="password" minLength={8} required/><small>Minimum 8 characters. Share securely.</small></label>}</div><footer><span>Historical activity is preserved.</span><div><button type="button" onClick={close}>Cancel</button><button className="primary">Save employee</button></div></footer></form></div>}
function DeactivateModal({employee,employees,close,submit}:{employee:Employee;employees:Employee[];close:()=>void;submit:(id:string)=>Promise<void>}){const[selected,setSelected]=useState("");return <div className="modal-backdrop centered"><section className="new-lead-modal compact-modal"><header><div><p className="eyebrow">SAFE DEACTIVATION</p><h2>Transfer active leads</h2></div><button className="close" onClick={close}>×</button></header><div className="deactivate-content"><p><strong>{employee.displayName}</strong> currently owns {employee.activeLeads} active leads. Choose another employee before deactivation.</p><label>Transfer active leads to<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select employee</option>{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select></label></div><footer><span>No lead will be orphaned.</span><div><button onClick={close}>Cancel</button><button className="primary" disabled={!selected} onClick={()=>void submit(selected)}>Transfer and deactivate</button></div></footer></section></div>}
function ProductionSettingsView({templates,user,company,rules,employees,sources,lostReasons,audit,save,reload,loadAudit,handleError,notify}:{templates:MessageTemplate[];user:User;company:CompanySettings;rules:AttentionRules;employees:Employee[];sources:Option[];lostReasons:Option[];audit:AuditItem[];save:(payload:Record<string,unknown>)=>Promise<void>;reload:()=>Promise<void>;loadAudit:(params?:string)=>Promise<void>;handleError:(error:unknown)=>void;notify:(message:string)=>void}){
  const[tab,setTab]=useState<"Company"|"Employees"|"Sources & reasons"|"Attention rules"|"Audit log"|"Message templates">("Employees");const[employeeModal,setEmployeeModal]=useState<Employee|"new"|null>(null);const[deactivate,setDeactivate]=useState<Employee|null>(null);const[newSource,setNewSource]=useState("");const[newReason,setNewReason]=useState("");
  useEffect(()=>{if(tab==="Audit log")void loadAudit();},[tab]);
  const saveEmployee=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);const isNew=employeeModal==="new";const payload={firstName:safeText(data.get("firstName")),lastName:safeText(data.get("lastName")),displayName:safeText(data.get("displayName")),email:safeText(data.get("email")),phone:safeText(data.get("phone"))||null,role:safeText(data.get("role")) as Role,...(isNew?{password:safeText(data.get("password"))}:{version:(employeeModal as Employee).version})};try{await api(isNew?"/api/employees":`/api/employees/${(employeeModal as Employee).id}`,{method:isNew?"POST":"PATCH",body:JSON.stringify(payload)});setEmployeeModal(null);await reload();notify(isNew?"Employee added":"Employee updated");}catch(error){handleError(error)}};
  const deactivateNow=async(employee:Employee,transferToUserId?:string)=>{try{await api(`/api/employees/${employee.id}/deactivate`,{method:"POST",body:JSON.stringify({transferToUserId:transferToUserId||undefined})});setDeactivate(null);await reload();notify("Employee deactivated safely")}catch(error){handleError(error)}};
  const reactivate=async(employee:Employee)=>{try{await api(`/api/employees/${employee.id}`,{method:"PATCH",body:JSON.stringify({version:employee.version,isActive:true})});await reload();notify("Employee reactivated")}catch(error){handleError(error)}};
  const addOption=async(type:"sources"|"lost-reasons",name:string,clear:()=>void)=>{try{await api(`/api/options/${type}`,{method:"POST",body:JSON.stringify({name})});clear();await reload();notify(type==="sources"?"Lead source added":"Lost reason added")}catch(error){handleError(error)}};
  const toggleOption=async(type:"sources"|"lost-reasons",item:Option)=>{try{await api(`/api/options/${type}/${item.id}`,{method:"PATCH",body:JSON.stringify({isActive:!item.is_active})});await reload();notify(`${item.name} ${item.is_active?"disabled":"enabled"}`)}catch(error){handleError(error)}};
  const filterAudit=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);const params=new URLSearchParams();for(const key of ["userId","leadId","action","from","to"]){const value=safeText(data.get(key));if(value)params.set(key,value)}void loadAudit(params.toString())};
  return <div className="page settings-page"><div className="settings-nav">{(["Employees",...(user.role==="Reception"?[]:["Company","Sources & reasons","Attention rules","Message templates","Audit log"])] as const).map(item=><button className={tab===item?"active":""} key={item} onClick={()=>setTab(item as typeof tab)}>{item}</button>)}</div><div className="settings-content">
    {tab==="Company"&&<form className="surface" onSubmit={event=>{event.preventDefault();const data=new FormData(event.currentTarget);void save({company:{companyName:safeText(data.get("companyName")),timezone:safeText(data.get("timezone")),currency:safeText(data.get("currency")).toUpperCase(),internalUrl:safeText(data.get("internalUrl"))}})}}><div className="panel-heading"><div><p className="eyebrow">WORKSPACE</p><h2>Company settings</h2></div><span>Saved to the CRM database</span></div><div className="settings-form"><label>Company name<input name="companyName" defaultValue={company.companyName} required/></label><label>Timezone<select name="timezone" defaultValue={company.timezone}><option>Asia/Dubai</option><option>UTC</option></select></label><label>Default currency<input name="currency" defaultValue={company.currency} minLength={3} maxLength={3} required/></label><label>Internal CRM address<input name="internalUrl" type="url" defaultValue={company.internalUrl}/></label><button className="primary">Save company settings</button></div></form>}
    {tab==="Attention rules"&&<form className="surface rules-card" onSubmit={event=>{event.preventDefault();const data=new FormData(event.currentTarget);void save({attentionRules:{highlightStale:data.get("highlightStale")==="on",newLeadHours:Number(data.get("newLeadHours")),inactiveLeadHours:Number(data.get("inactiveLeadHours")),flagMissingFollowUp:data.get("flagMissingFollowUp")==="on",flagUnassigned:data.get("flagUnassigned")==="on"}})}}><div className="panel-heading"><div><p className="eyebrow">ACCOUNTABILITY</p><h2>Lead attention rules</h2></div><span>Used by dashboard and filters</span></div><label><div><strong>Red cards after 3 days</strong><small>No recorded call, message, note or status update for 72 hours</small></div><input name="highlightStale" type="checkbox" defaultChecked={rules.highlightStale!==false}/></label><label><div><strong>New lead untouched</strong><small>Warn when a New lead has no recent activity</small></div><span>After <input name="newLeadHours" type="number" min="1" max="720" defaultValue={rules.newLeadHours}/> hours</span></label><label><div><strong>Active lead inactive</strong><small>Warn when no activity is recorded</small></div><span>After <input name="inactiveLeadHours" type="number" min="1" max="2160" defaultValue={rules.inactiveLeadHours}/> hours</span></label><label><div><strong>Missing next follow-up</strong><small>Flag active leads without a scheduled next step</small></div><input name="flagMissingFollowUp" type="checkbox" defaultChecked={rules.flagMissingFollowUp}/></label><label><div><strong>Unassigned active lead</strong><small>Show active leads without an owner</small></div><input name="flagUnassigned" type="checkbox" defaultChecked={rules.flagUnassigned}/></label><button className="primary settings-save">Save attention rules</button></form>}
    {tab==="Employees"&&<EmployeesPanel user={user} employees={employees} reload={reload}/>}{tab==="Message templates"&&<TemplatesEditor templates={templates} reload={reload}/>}
    {tab==="Sources & reasons"&&<div className="option-grid"><OptionEditor title="Lead sources" description="Available in lead creation and filters." items={sources} value={newSource} setValue={setNewSource} add={()=>void addOption("sources",newSource,()=>setNewSource(""))} toggle={item=>void toggleOption("sources",item)}/><OptionEditor title="Lost reasons" description="Required when a lead is marked Lost." items={lostReasons} value={newReason} setValue={setNewReason} add={()=>void addOption("lost-reasons",newReason,()=>setNewReason(""))} toggle={item=>void toggleOption("lost-reasons",item)}/></div>}
    {tab==="Audit log"&&<section className="surface"><div className="panel-heading"><div><p className="eyebrow">APPEND-ONLY HISTORY</p><h2>Audit log</h2></div>{user.role!=="Reception"&&<a className="text-link" href="/api/export/audit.csv">Export CSV</a>}</div><form className="audit-filters" onSubmit={filterAudit}><select name="userId" defaultValue=""><option value="">All users</option>{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select><input name="leadId" inputMode="numeric" placeholder="Lead ID"/><input name="action" placeholder="Action contains…"/><input name="from" type="date" aria-label="From date"/><input name="to" type="date" aria-label="To date"/><button>Apply filters</button><button type="button" onClick={()=>void loadAudit()}>Clear</button></form><div className="audit-list">{audit.map(item=><article key={item.id}><time>{formatDate(item.timestamp)}</time><div><strong>{item.user_name} · {item.action}</strong><p>{item.entity_type} {item.entity_id}{item.field_changed?` · ${item.field_changed}`:""}</p>{(item.old_value||item.new_value)&&<small>{item.old_value??"—"} → {item.new_value??"—"}</small>}</div></article>)}{!audit.length&&<Empty title="No audit history for this filter" text="Try a wider date range or clear the filters."/>}</div></section>}
  </div>{employeeModal&&<ScopedEmployeeModal item={employeeModal} actorRole={user.role} close={()=>setEmployeeModal(null)} submit={saveEmployee}/>} {deactivate&&<DeactivateModal employee={deactivate} employees={employees.filter(item=>item.isActive&&item.id!==deactivate.id)} close={()=>setDeactivate(null)} submit={id=>deactivateNow(deactivate,id)}/>}</div>
}

function ScopedEmployeeModal({item,actorRole,close,submit}:{item:Employee|"new";actorRole:Role;close:()=>void;submit:(event:FormEvent<HTMLFormElement>)=>void}){const isNew=item==="new";const roles:Role[]=actorRole==="Administrator"?["Administrator","Manager","Sales Employee"]:["Sales Employee"];return <div className="modal-backdrop centered"><form className="new-lead-modal compact-modal" onSubmit={submit}><header><div><p className="eyebrow">TEAM MEMBER</p><h2>{isNew?"Add employee":"Edit employee"}</h2></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-grid"><label>First name *<input name="firstName" required defaultValue={isNew?"":item.firstName}/></label><label>Last name *<input name="lastName" required defaultValue={isNew?"":item.lastName}/></label><label className="wide">Display name *<input name="displayName" required defaultValue={isNew?"":item.displayName}/></label><label>Email *<input name="email" type="email" required defaultValue={isNew?"":item.email}/></label><label>Phone<input name="phone" defaultValue={isNew?"":item.phone}/></label><label>Role<select name="role" defaultValue={isNew?roles.at(-1):item.role}>{roles.map(role=><option key={role}>{role}</option>)}</select></label>{isNew&&<label className="wide">Temporary password *<input name="password" type="password" minLength={8} required/><small>Minimum 8 characters. Share securely.</small></label>}</div><footer><span>Historical activity is preserved.</span><div><button type="button" onClick={close}>Cancel</button><button className="primary">Save employee</button></div></footer></form></div>}

function OptionEditor({title,description,items,value,setValue,add,toggle}:{title:string;description:string;items:Option[];value:string;setValue:(value:string)=>void;add:()=>void;toggle:(item:Option)=>void}){return <section className="surface option-editor"><div className="panel-heading"><div><p className="eyebrow">CONFIGURATION</p><h2>{title}</h2></div></div><p>{description}</p><div className="option-add"><input value={value} onChange={event=>setValue(event.target.value)} minLength={2} maxLength={100} placeholder={`New ${safeLower(title).replace(/s$/,"")}`}/><button className="primary small" disabled={value.trim().length<2} onClick={add}>Add</button></div><div className="option-list">{items.map(item=><div key={item.id}><span>{item.name}</span><small>{item.is_active?"Active":"Inactive"}</small><button onClick={()=>toggle(item)}>{item.is_active?"Disable":"Enable"}</button></div>)}</div></section>}

function NewCalendarEventModal({close,submit,leads,employees,defaultLeadId,busy}:{close:()=>void;submit:(e:FormEvent<HTMLFormElement>)=>void;leads:Lead[];employees:Employee[];defaultLeadId:number|null;busy:boolean}){return <div className="modal-backdrop centered" onMouseDown={event=>event.target===event.currentTarget&&close()}><form className="new-lead-modal compact-modal" onSubmit={submit}><header><div><p className="eyebrow">APPOINTMENT</p><h2>Schedule viewing or meeting</h2></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-grid"><label className="wide">Title *<input name="title" required autoFocus placeholder="Marina apartment viewing"/></label><label>Type *<select name="eventType" defaultValue="viewing"><option value="viewing">Viewing</option><option value="meeting">Meeting</option></select></label><label>Related lead *<select name="leadId" required defaultValue={defaultLeadId??""}><option value="" disabled>Select lead</option>{leads.filter(item=>!isClosed(item)).map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>Starts *<input name="startsAt" type="datetime-local" required/></label><label>Ends<input name="endsAt" type="datetime-local"/></label><label className="wide">Assigned employee *<select name="assignedUserId" required defaultValue=""><option value="" disabled>Select employee</option>{employees.map(item=><option value={item.id} key={item.id}>{item.displayName}</option>)}</select></label></div><footer><span>The appointment appears in the calendar and lead history.</span><div><button type="button" onClick={close}>Cancel</button><button className="primary" disabled={busy}>{busy?"Saving…":"Schedule"}</button></div></footer></form></div>}

function PersistentCalendarView({leads,tasks,scheduled,open,add}:{leads:Lead[];tasks:Task[];scheduled:CalendarEvent[];open:(id:number)=>void;add:()=>void}){
  const[mode,setMode]=useState<"Day"|"Week"|"Month">("Month");const[cursor,setCursor]=useState(new Date());
  const events=[...leads.filter(lead=>lead.followUp).map(lead=>({id:`f${lead.id}`,at:new Date(lead.followUp!),title:`Follow-up · ${lead.name}`,leadId:lead.id,type:"follow"})),...tasks.filter(task=>!task.done).map(task=>({id:`t${task.id}`,at:new Date(task.dueAt),title:`Task · ${task.title}`,leadId:task.leadId,type:"task"})),...scheduled.map(item=>({id:`e${item.id}`,at:new Date(item.startsAt),title:`${item.eventType==="viewing"?"Viewing":"Meeting"} · ${item.title}`,leadId:item.leadId,type:item.eventType}))].filter(item=>!Number.isNaN(item.at.getTime()));
  const monthStart=new Date(cursor.getFullYear(),cursor.getMonth(),1);const offset=(monthStart.getDay()+6)%7;const days=Array.from({length:42},(_,index)=>new Date(cursor.getFullYear(),cursor.getMonth(),index-offset+1));const dayStart=new Date(cursor.getFullYear(),cursor.getMonth(),cursor.getDate());const weekStart=new Date(dayStart);weekStart.setDate(dayStart.getDate()-((dayStart.getDay()+6)%7));const weekEnd=new Date(weekStart.getTime()+7*86400000);
  const periodEvents=events.filter(event=>mode==="Day"?event.at.toDateString()===cursor.toDateString():mode==="Week"?event.at>=weekStart&&event.at<weekEnd:event.at.getMonth()===cursor.getMonth()&&event.at.getFullYear()===cursor.getFullYear());
  const move=(direction:number)=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+(mode==="Month"?direction:0),cursor.getDate()+(mode==="Week"?direction*7:mode==="Day"?direction:0)));
  return <div className="page"><div className="calendar-toolbar"><div className="segmented">{(["Day","Week","Month"] as const).map(item=><button key={item} className={mode===item?"active":""} onClick={()=>setMode(item)}>{item}</button>)}</div><div><button onClick={()=>move(-1)}>‹</button><h2>{mode==="Month"?new Intl.DateTimeFormat("en-AE",{month:"long",year:"numeric"}).format(cursor):mode==="Week"?`Week of ${formatDate(weekStart.toISOString(),false)}`:formatDate(cursor.toISOString(),false)}</h2><button onClick={()=>move(1)}>›</button></div><button onClick={()=>setCursor(new Date())}>Today</button><button className="primary" onClick={add}>＋ Schedule</button></div>{mode==="Month"?<div className="calendar-grid">{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(day=><b className="weekday" key={day}>{day}</b>)}{days.map(day=><div className={`calendar-day ${day.toDateString()===new Date().toDateString()?"today":""} ${day.getMonth()!==cursor.getMonth()?"muted":""}`} key={day.toISOString()}><span>{day.getDate()}</span>{events.filter(event=>event.at.toDateString()===day.toDateString()).slice(0,4).map(event=><button key={event.id} className={event.type==="task"?"task-event":event.type} onClick={()=>event.leadId&&open(event.leadId)}><i/>{event.at.toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})} · {event.title}</button>)}</div>)}</div>:<div className="surface calendar-agenda">{periodEvents.sort((a,b)=>a.at.getTime()-b.at.getTime()).map(event=><button key={event.id} onClick={()=>event.leadId&&open(event.leadId)}><time>{formatDate(event.at.toISOString())}</time><i className={event.type}/><strong>{event.title}</strong><span>{event.leadId?"Open lead →":"No related lead"}</span></button>)}{!periodEvents.length&&<Empty title="No calendar events" text="Follow-ups, tasks, viewings and meetings appear here."/>}</div>}</div>
}

function ProductionReportsView({reports,metrics}:{reports:ReportData;metrics:DashboardMetrics}){return <><div className="export-toolbar"><span>Export business data</span><a href="/api/export/leads.csv">Leads CSV</a><a href="/api/export/tasks.csv">Tasks CSV</a><a href="/api/export/employee-performance.csv">Employee performance</a><a href="/api/export/lead-sources.csv">Lead sources</a><a href="/api/export/closed-leads.csv">Won / Lost</a></div><ReportsView reports={reports} metrics={metrics}/><section className="surface response-report"><div className="panel-heading"><h2>First response time</h2></div><p className="operations-help">Time from lead creation to the first recorded answered call or sent WhatsApp/email. Opening a communication link is not counted. Grouped by current owner.</p><div className="table-wrap"><table><thead><tr><th>Employee</th><th>Total leads</th><th>Contacted</th><th>Average response time</th></tr></thead><tbody>{reports.responseTimes?.map(r=><tr key={r.id}><td>{r.display_name}</td><td>{r.total}</td><td>{r.contacted}</td><td>{r.average_minutes==null?"No recorded contact":r.average_minutes<60?`${Math.round(r.average_minutes)} minutes`:`${(r.average_minutes/60).toFixed(1)} hours`}</td></tr>)}</tbody></table></div></section></>}

function Empty({title,text}:{title:string;text:string}){return <div className="empty-state"><b>{title}</b><p>{text}</p></div>}
